"""A simulated 20-minute run on virtual time: the real orchestrator, agents, analysts, calculator, coordinator, ERP
scheduler and submitter, against fake sites and a fake model. Everything is invented (no challenge data).

Each fake browse step and model call takes virtual seconds, so a whole run takes about a second of real time.
A fake page carries its extraction answer as JSON after `SIMDATA:`; the fake model returns it, so analysts run their
real rules on it. Faults can be injected: a stalled-then-crashing ERP tab, a crashing mail browse, slow steps, a spec
site that never yields its requirement table.

    report = run_simulation(Faults(stall_erp=True, crash_mail=True, step_s=20))
"""
import asyncio
import json
import math
import re
import time
from dataclasses import dataclass, field
from unittest import mock

from swarm import timeline

REF = "SIM-7781"
SCENARIO = "2031-02-01T09:00:00Z"
BRIEF = f"""# Angebot {REF}
Wir sind die Muster Fluidtechnik GmbH (USt-IdNr. DE000000001). Ausschreibung {REF} der Stadt Beispielhausen.
Stichtag {SCENARIO}. Rabattfreigaben nur von leitung@muster.example; Verpackungstarife von logistik@muster.example.

## Regeln
Mengen laut Leistungsverzeichnis, geändert durch die letzte Bieterfrage.

## Submission
Submit the bid through the tender portal and sign it with the TAN from the webmail.
"""
SITES = [{"siteId": s, "url": f"https://{s}.sim.example", "credentials": {"username": "u", "password": "REDACTED"}}
         for s in ("tp", "cp", "erp", "mail")]

REQS = {"R-A": dict(bore="40", stroke="100", pressure="160", mounting="Flansch", certification="keine", kataloggruppe="G-A"),
        "R-B": dict(bore="63", stroke="200", pressure="160", mounting="Flansch", certification="keine", kataloggruppe="G-B"),
        "R-C": dict(bore="80", stroke="300", pressure="250", mounting="Gelenk", certification="keine", kataloggruppe="G-C")}
MATERIALS = {"X-11": ("R-A", True), "X-12": ("R-A", False), "X-21": ("R-B", True), "X-31": ("R-C", True),
             "X-32": ("R-C", False)}


def material_row(no: str, full: bool) -> dict:
    ref, fits = MATERIALS[no]
    row = {"material": no, "kataloggruppe": REQS[ref]["kataloggruppe"], **{k: REQS[ref][k] for k in
                                                                          ("bore", "stroke", "pressure", "mounting")}}
    if not fits:
        row["pressure"] = "400"
    if full:
        row.update(certification="keine", is_active=True, status_code="01", lead_time_stock_weeks="2",
                   lead_time_production_weeks="7", pieces_per_carton="4", surcharge_mass_g="0")
    return row


@dataclass
class Faults:
    step_s: float = 12.0              # one browsing step (flash) in virtual seconds
    submit_step_s: float = 18.0       # one submitter step (full reasoning)
    model_s: float = 4.0              # one analysis/planning model call
    stall_erp: bool = False           # first prices read of X-21 hangs 300 s, then the browser agent crashes
    crash_mail: bool = False          # the first mail index browse crashes after saving one page
    no_spec: bool = False             # the spec site never yields its requirement table


@dataclass
class World:
    faults: Faults
    browses: list = field(default_factory=list)       # (start, end, author, job head, outcome)
    counts: dict = field(default_factory=dict)
    page: str = ""

    def first(self, key: str) -> bool:
        self.counts[key] = self.counts.get(key, 0) + 1
        return self.counts[key] == 1


def page(topic: str, url: str, data: dict) -> dict:
    return {"kind": "page", "data": {"topic": topic, "url": url, "text": "SIMDATA:" + json.dumps(data)},
            "source": url, "note": ""}


def plan(world: World, author: str, job: str) -> tuple[list, bool, str]:
    """(steps [(seconds, record or None)], done, summary) for a fake browse."""
    f, s = world.faults, world.faults.step_s
    head = job.split("YOUR JOB:")[-1].strip()
    if author.startswith("TenderScraper"):
        if "bidder questions" in head or "Bieterfragen" in head:
            qa = {"clarifications": [
                {"number": "1", "date": "2031-01-10T10:00:00Z", "kind": "quantity_change", "positions": ["P2"],
                 "new_quantity": "5"},
                {"number": "2", "date": "2031-01-11T10:00:00Z", "kind": "commercial_keys", "positions": ["P1"],
                 "keys": {"packaging_tariff": "PK-1"}}]}
            return [(s, None), (s, None), (s, page("bidder Q&A", "https://tp.sim.example/qa", qa))], True, "Q&A saved"
        if "documents" in head or "bill of quantities" in head:
            bq = {"meta": {"reference": REF}, "positions": [
                {"position": "P1", "quantity": "10", "unit": "Stk", "requirement_ref": "R-A"},
                {"position": "P2", "quantity": "4", "unit": "Stk", "requirement_ref": "R-B"},
                {"position": "P3", "quantity": "6", "unit": "Stk", "requirement_ref": "R-C"}]}
            return [(s, None), (s, page("bill of quantities", "https://tp.sim.example/docs/1", bq))], True, "saved"
        return [(s, None), (s, None), (s, page("tender overview", "https://tp.sim.example/t", {"meta": {"reference": REF}}))], \
            True, "overview saved"
    if author.startswith("SpecScraper"):
        if f.no_spec:
            return [(s, None)] * 6, False, "requirement table viewer did not load"
        spec = {"revisions": [{"revision": "REV-1", "is_current": False, "date": "2030-11-01"},
                              {"revision": "REV-2", "is_current": True, "date": "2031-01-05"}],
                "requirements": [dict(ref=r, revision="REV-2", **v) for r, v in REQS.items()]
                + [dict(ref="R-A", revision="REV-1", **dict(REQS["R-A"], bore="45"))]}
        return [(s, None)] * 4 + [(s, page("spec requirements REV-2", "https://cp.sim.example/spec", spec))], True, "saved"
    if author.startswith("ErpScraper"):
        group = re.search(r"Kataloggruppe\) (G-\w)", head)
        if "Find our ERP materials" in head and group:
            rows = [material_row(no, False) for no, (ref, _) in MATERIALS.items()
                    if REQS[ref]["kataloggruppe"] == group.group(1)]
            return [(s, None), (s, None), (s, page(f"erp search {group.group(1)}",
                                                   f"https://erp.sim.example/f4?g={group.group(1)}", {"materials": rows}))], \
                True, "list saved"
        material = re.search(r"material (X-\d\d)", head)
        if material is None:
            return [(s, None)] * 4, True, "logged in, search help open"
        no = material.group(1)
        if head.startswith("Price conditions") or "Price conditions of material" in head:
            if no == "X-21" and f.stall_erp and world.first("stall X-21"):
                return [(300.0, None), (0, "crash")], False, ""
            if no == "X-11":
                header = {"conditions": [{"material": no, "record": "K-11", "valid_from": "2031-01-01",
                                          "valid_to": "2031-12-31", "price_unit": "1", "currency": "EUR", "scales": []},
                                         {"material": no, "record": "K-10", "valid_from": "2030-01-01",
                                          "valid_to": "2030-12-31", "price_unit": "1",
                                          "scales": [{"min_qty": "1", "price": "999"}]}]}
                scales = {"conditions": [{"material": no, "scales": [{"min_qty": "1", "price": "120"},
                                                                     {"min_qty": "10", "price": "100"}]}]}
                return [(s, None), (s, page(f"erp prices {no}", f"https://erp.sim.example/cond/{no}", header)),
                        (s, page(f"erp prices {no}", f"https://erp.sim.example/cond/{no}/scales", scales))], True, "saved"
            cond = {"material": no, "record": f"K-{no[-2:]}", "valid_from": "2031-01-01", "valid_to": "2031-12-31",
                    "currency": "EUR", "scales": [{"min_qty": "1", "price": "80" if no == "X-21" else "60"}]}
            if no != "X-31" or "did NOT show" in head:
                cond["price_unit"] = "1"                      # X-31's price unit only shows on a focused re-read
            url = f"https://erp.sim.example/cond/{no}" + ("/header" if "did NOT show" in head else "")
            return [(s, None), (s, page(f"erp prices {no}", url, {"conditions": [cond]}))], True, "saved"
        if head.startswith("Stock of material"):
            stock = {"stock": [{"material": no, "plant": "1000", "location": "L1", "quantity": "50", "usable": True}]}
            return [(s, None), (s, page(f"erp stock {no}", f"https://erp.sim.example/stock/{no}", stock))], True, "saved"
        return [(s, None), (s, page(f"erp material {no}", f"https://erp.sim.example/mat/{no}",
                                    {"materials": [material_row(no, True)]}))], True, "saved"
    if author.startswith("MailScraper"):
        owner = "vertrieb@muster.example"
        approval = {"mailbox_owner": owner, "messages": [
            {"subject": f"Rabattfreigabe {REF}", "sender": "leitung@muster.example", "date": "2031-01-20T10:00:00Z",
             "reference": REF, "topic": "discount_approval", "discount_percent": 5, "entries": []},
            {"subject": f"Rabattfreigabe {REF}-B", "sender": "leitung@muster.example", "date": "2031-01-25T10:00:00Z",
             "reference": f"{REF}-B", "topic": "discount_approval", "discount_percent": 50, "entries": []}]}
        packaging = {"mailbox_owner": owner, "messages": [
            {"subject": "Verpackungstarif", "sender": "logistik@muster.example", "date": "2031-01-15T10:00:00Z",
             "reference": REF, "topic": "packaging_tariffs", "entries": [{"key": "PK-1", "eur_per_carton": 4.5}]}]}
        if "Search the exact tender reference ALONE" in head:
            steps = [(s, None), (s, page("mail messages", "https://mail.sim.example/m/1", approval))]
            if f.crash_mail and world.first("crash mail"):
                return steps + [(s, None), (0, "crash")], False, ""
            return steps + [(s, None)], True, "read 2 messages"
        if "Verpackung" in head or "packaging" in head.lower():
            return [(s, None), (s, None), (s, page("Verpackung mail", "https://mail.sim.example/m/7", packaging))], \
                True, "packaging tariff saved"
        return [(s, None)] * 3, True, "inbox open"
    return [(s, None)] * 2, True, "done"


async def fake_browse(world: World, ctx, goal: str, *, author: str = "browse", on_record=None, stop_reserve=None,
                      stop_extra: float = 0.0, extra_tools=None, **kwargs) -> dict:
    """Stands in for swarm.browser_agent.browse: steps take virtual time, pages reach on_record, the stop mark is
    checked before every step like the real one, and steps are measured on the timeline."""
    start = timeline.now()
    token = timeline.AGENT.set(author)
    records: list = []

    async def emit(rec):
        records.append(rec)
        if on_record:
            await on_record(rec)
    try:
        if author.startswith("BidSubmitter"):
            return await fake_submit(world, ctx, goal, author, emit, stop_reserve, extra_tools)
        steps, done, summary = plan(world, author, goal)
        for i, (seconds, record) in enumerate(steps):
            mark = stop_reserve if stop_reserve is not None else ctx.stop_at(stop_extra)
            if ctx.seconds_left() <= mark:
                done, summary = False, "stopped: collection time is up"
                break
            if record == "crash":
                world.browses.append((start, timeline.now(), author, goal.split("YOUR JOB:")[-1][:60], "crash"))
                raise RuntimeError("Browser state capture timed out (simulated)")
            step_start = timeline.now()
            await asyncio.sleep(seconds)
            timeline.add("browse.step", "step", step_start)
            if record:
                await emit(record)
        world.browses.append((start, timeline.now(), author, goal.split("YOUR JOB:")[-1][:60], "done" if done else "stopped"))
        return {"summary": summary, "done": done, "records": records, "steps": len(steps)}
    finally:
        timeline.AGENT.reset(token)


class Session:
    async def get_current_page_url(self):
        return "https://tp.sim.example/bid/receipt"


async def fake_submit(world: World, ctx, goal: str, author: str, emit, stop_reserve, extra_tools) -> dict:
    from agents import submit_bid
    from swarm.browser_agent import build_tools
    s = world.faults.submit_step_s
    if author.endswith(".tan"):
        for _ in range(3):
            await asyncio.sleep(world.faults.step_s)
        await emit({"kind": "mail.tan", "data": {"tan": "424242"}, "source": "https://mail.sim.example/tan", "note": ""})
        return {"summary": "TAN 424242", "done": True, "records": [], "steps": 3}
    if author.endswith(".mailbox"):
        for _ in range(3):
            await asyncio.sleep(world.faults.step_s)
        return {"summary": "inbox open", "done": True, "records": [], "steps": 3}
    if author == "WizardPrep":
        for _ in range(5):
            await asyncio.sleep(world.faults.step_s)
        return {"summary": "wizard open at step 1 of 6", "done": True, "records": [], "steps": 5}
    tools = build_tools(ctx, "tp", author, emit)
    extra_tools(tools)
    actions = tools.registry.registry.actions
    positions = goal.count("-> material ")
    entry_steps = (2 if "PREPARED:" in goal else 6) + math.ceil(2.5 * positions) + 2
    for _ in range(entry_steps):
        if ctx.seconds_left() <= stop_reserve:
            return {"summary": "out of time in the wizard", "done": False, "records": [], "steps": entry_steps}
        await asyncio.sleep(s)
    bid = ctx.board.get("bid") or {}
    expected = submit_bid.expected_values(bid)
    world.page = "Zusammenfassung " + " ".join(v for vals in expected.values() for v in vals)
    check = await actions["check_entries"].function(params=submit_bid.CheckParams(note="summary"),
                                                    browser_session=Session())
    world.counts["check"] = check.extracted_content
    await asyncio.sleep(s)                                             # request the TAN
    result = await actions["get_signing_tan"].function(params=submit_bid.TanParams())
    while "TAN:" not in (result.extracted_content or ""):
        await asyncio.sleep(s)
        result = await actions["get_signing_tan"].function(params=submit_bid.TanParams())
    await asyncio.sleep(2 * s)                                         # enter TAN, confirm in the dialog
    world.page = f"Angebot {REF} wurde verbindlich abgegeben. Eingangsnummer 7"
    receipt = await actions["confirm_submission"].function(
        params=submit_bid.ReceiptParams(quote=f"Angebot {REF} wurde verbindlich abgegeben.", reference=REF),
        browser_session=Session())
    return {"summary": "receipt confirmed", "done": bool(receipt.success), "records": [], "steps": entry_steps + 4}


class FakeLLM:
    """The model: brief facts, site roles, follow-up plans, and page extraction (the page's SIMDATA)."""

    def __init__(self, world: World):
        self.world, self.calls, self.tokens, self._client = world, 0, {"prompt": 0, "completion": 0}, None
        self._sem = asyncio.Semaphore(16)

    async def ask_json(self, system: str, user: str, **kwargs):
        self.calls += 1
        with timeline.span("model.call", "fake"):
            await asyncio.sleep(self.world.faults.model_s)
        if "Extract key facts from task brief" in system:
            return {"tender_reference": REF, "scenario_date": SCENARIO, "bidder_company": "Muster Fluidtechnik GmbH",
                    "bidder_vat_id": "DE000000001", "director_sender": "leitung@",
                    "authorized_senders": {"discount_approval": "leitung@", "packaging_tariffs": "logistik@"},
                    "topic_words": {"discount_approval": "Rabatt", "packaging_tariffs": "Verpackung"}}
        if "Map roles to siteId" in system:
            return {"tender": "tp", "spec": "cp", "erp": "erp", "mail": "mail"}
        if system.startswith("You coordinate browser agents"):
            gaps = json.loads(user)["gaps"]
            return {"jobs": [{"role": g["role"], "gaps": [g["id"]], "job": f"Collect: {g['need']}"} for g in gaps[:6]]}
        found = re.search(r"SIMDATA:(\{.*\})", user, re.S)
        return json.loads(found.group(1)) if found else {}

    async def ask(self, system, user, **kwargs):
        return json.dumps(await self.ask_json(system, user))

    async def chat(self, messages, **kwargs):
        raise RuntimeError("no free-form chat in the simulation")


class VirtualClock:
    """Virtual time for an event loop: whenever the loop would sleep, the clock jumps to the next timer instead."""

    def __init__(self):
        self.t = 0.0
        self.base = time.monotonic()

    def loop(self) -> asyncio.AbstractEventLoop:
        loop = asyncio.SelectorEventLoop()
        loop.time = lambda: self.t
        select = loop._selector.select

        def jump(timeout=None):
            if timeout is not None and timeout > 0:
                self.t += timeout
            return select(0)
        loop._selector.select = jump
        return loop

    def monotonic(self) -> float:
        return self.base + self.t


def run_simulation(faults: Faults | None = None) -> dict:
    """Run the whole swarm once on virtual time; returns what happened (outcome, timeline report, bid, browses)."""
    from agents import submit_bid
    from swarm import orchestrator, scraper
    world = World(faults or Faults())
    clock = VirtualClock()
    task = {"brief": BRIEF, "access": SITES, "submission": {"kind": "site", "url": "https://tp.sim.example"},
            "answer_schema": None}

    async def browse(ctx, goal, **kwargs):
        return await fake_browse(world, ctx, goal, **kwargs)

    async def page_text(session):
        return world.page

    outcome = {"accepted": False, "error": None}
    holder = {}

    async def main():
        from swarm.blackboard import Blackboard
        original = Blackboard.__init__

        def keep(board):
            original(board)
            holder["board"] = board
        with mock.patch.object(Blackboard, "__init__", keep):
            try:
                await orchestrator.run_swarm(task, None, scored=True, env={})
                outcome["accepted"] = True
            except Exception as error:  # noqa: BLE001
                outcome["error"] = f"{type(error).__name__}: {error}"

    loop = clock.loop()
    try:
        with mock.patch("time.monotonic", clock.monotonic), \
                mock.patch.object(orchestrator, "LLM", lambda: FakeLLM(world)), \
                mock.patch.object(scraper, "browse", browse), mock.patch.object(submit_bid, "browse", browse), \
                mock.patch.object(submit_bid, "read_current_page", page_text):
            loop.run_until_complete(main())
    finally:
        loop.close()
    tl = timeline.current()
    board = holder.get("board")
    return {"outcome": outcome, "report": tl.report(), "milestones": {k: v[0] for k, v in tl.milestones.items()},
            "bid": board.get("bid") if board else None, "board": board, "world": world, "timeline": tl}
